import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { GAccount } from '../../../../core/common/GAccount';
import { Urls } from '../../../../core/common/Urls';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { AlertController } from '@ionic/angular';

@Component({
  selector: 'app-teacher-active',
  templateUrl: './teacher-active.component.html',
  styleUrls: ['./teacher-active.component.scss']
})
export class TeacherActiveComponent implements OnInit {

  constructor(
    private router: Router,
    public alertController: AlertController
  ) { }

  ngOnInit(): void {

    this.presentConfirm();
  }

  async presentConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'توجه',
      message: 'اکانت شما فعال شد. لطفا مجدد لاگین کنید',
      backdropDismiss: false,
      buttons: [
        {
          text: 'متوجه شدم',
          role: 'cancel',
          cssClass: 'success',
          handler: () => {
            GAccount.SignOut();
            this.router.navigateByUrl(Urls.AccountUrl);
          }
        }
      ]
    });

    await alert.present();
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

}
